    (3, 8280, 'TROMBINA DADE REACTIVO (CARDIOSERVICIOS)', 9, null, null, 1),
    (3, 8281, 'TUBO ARTICULADO COLLES 180MM CON PINES 2.5MM Y 3.0M TECMED', 9, null, null, 1),
    (3, 8282, 'TUBO DE ARTROSCOPIA  ORTOGUA', 9, null, null, 1),
