    (3, 8288, 'TUBO DE COMPRESION  *', 9, null, null, 1),
    (3, 8289, 'TUBO DE IRRIGACION PARA BOMBA  10 K REF. 10K1000', 9, null, null, 1),
    (3, 8290, 'TUBO FROVA INTERCAMBIADOR DE TUBO PEDIATRICO', 9, null, null, 1),
    (3, 8291, 'TUBO PARA BOMBA DE ARTROSCOPIA (MOALCONVER)', 9, null, null, 1),
    (3, 8292, 'TUERCA HEXAGONAL P/AJUSTADOR FACIL DORADO REPCA', 9, null, null, 1),
    (3, 8293, 'TUNELIZADORES PARA CATÉTER PERITONEAL ADULTO REF.TZCA65', 9, null, null, 1),
    (3, 8294, 'VALVULA  VENTRICULAR PRESION MEDIA MAQUI', 9, null, null, 1),
    (3, 8295, 'VALVULA ADULTA ALTA  REF. ADA-102150', 9, null, null, 1),
    (3, 8296, 'VÁLVULA DE PRESIÓN MEDIA ADULTO  REF. ADM10223D', 9, null, null, 1),
    (3, 8297, 'VALVULA INFANTIL PRESION MEDIA INM9015D MAQUI.', 9, null, null, 1),
    (3, 8298, 'VALVULA POLARIS PROGRAMABLE SPVA 2010', 9, null, null, 1),
    (3, 8299, 'VASTAGO AUTOBLOQUEANTE', 9, null, null, 1),
    (3, 8300, 'VASTAGO DE CADERA #13', 9, null, null, 1),
    (3, 8301, 'VASTAGO DE REVISIÓN ACCUMATH SERIE M CURVO 11X250MM OG *', 9, null, null, 1),
    (3, 8302, 'VASTAGO FEMORAL AUTOBLOQUEANTE/NO CEMENTADO ORTO', 9, null, null, 1),
    (3, 8303, 'VASTAGO NO CEMENTADO 135° 8.0 CONO 12/14 REF:29.00.39- SQ *', 9, null, null, 1),
    (3, 8304, 'XO BOTON', 9, null, null, 1),
    (3, 8305, 'ZERO- P - CONVENXO ALTURA 6 MM  REF.046171365.', 9, null, null, 1),
    (3, 8306, 'ZERO P CONVEXO ALTURA 5MM REF. 04-617-1356S', 9, null, null, 1),
    (3, 8307, 'ZERO -P CONVEXO ALTURA 6MM 04.617.136S', 9, null, null, 1),
    (3, 8308, 'ZERO-P CONVEXO ALTURA 5MM PEEK 04617135S ADMETECH *', 9, null, null, 1),
    (3, 8309, 'ALIMENTACION ENTERAL', 13, null, null, null),
    (3, 8310, 'INSUMOS QUIRURGICOS', 12, null, null, null),
    (3, 8311, 'CURACIONES', 12, null, null, null),
    (3, 8312, 'PENDIENTE DE DEFINIR', 13, null, null, null),
    (3, 8313, 'EMPAQUE PARA ESTERELIZAR', 14, null, null, null),
    (3, 8321, 'TRAUMAS', 22, null, null, null),
    (3, 8322, 'CIRUGÍA', 23, null, null, null)) as x(loc, codigo, nombre, clasificacion, c_inv, c_fac, ver) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    v_cla := null;
    select id into v_cla from public.clasificaciones_producto where localidad_id = v_loc and codigo_anterior = r.clasificacion;
    if v_cla is null then t_s := t_s + 1; continue; end if;
    v_cta := null; v_cf := null;
    if r.c_inv is not null then select c.id into v_cta from public.cuentas c where c.codigo = r.c_inv and public.cuenta_de_localidad(c.id, v_loc) limit 1; end if;
    if r.c_fac is not null then select c.id into v_cf from public.cuentas c where c.codigo = r.c_fac and public.cuenta_de_localidad(c.id, v_loc) limit 1; end if;
    v_id := null;
    select id into v_id from public.tipos_producto where localidad_id = v_loc and codigo_anterior = r.codigo;
    if v_id is null then
      insert into public.tipos_producto (clasificacion_id, organizacion_id, localidad_id, codigo, nombre, codigo_anterior)
      values (v_cla, v_org, v_loc, case when exists (select 1 from public.tipos_producto where localidad_id = v_loc and codigo = r.codigo)
        then (select greatest(coalesce(max(codigo), 0), case r.loc when 1 then 8320 when 2 then 6947 when 3 then 8322 else 0 end) + 1 from public.tipos_producto where localidad_id = v_loc) else r.codigo end, r.nombre, r.codigo)
      returning id into v_id;
      t_n := t_n + 1;
    else
      t_a := t_a + 1;
    end if;
    update public.tipos_producto set clasificacion_id = v_cla, nombre = r.nombre, codigo_anterior = r.codigo,
      cuenta_inventario_id = coalesce(v_cta, cuenta_inventario_id), cuenta_facturacion_id = coalesce(v_cf, cuenta_facturacion_id),
      cuenta_inventarios_anterior = r.c_inv, cuenta_facturacion_anterior = r.c_fac, version_anterior = r.ver::integer
    where id = v_id;
  end loop;
  raise notice '%', format('Tipos de producto: %s nuevos, %s actualizados, %s sin clasificación (ejecute antes la parte 1).', t_n, t_a, t_s);
end;
$migra$;

notify pgrst, 'reload schema';
